import { Component, ChangeDetectionStrategy, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { TranslateModule } from '@ngx-translate/core';
import { ContactService } from '@services/contact.service';
import { IconComponent } from '@components/ui/icon/icon.component';
import { ToastService } from '@services/toast.service';
import { ContactFormModalComponent } from '../../modals/contact-form-modal/contact-form-modal.component';
import { Contact } from '../../models/contact.model';
import { ConfirmModalService } from '../../services/confirm-modal.service';

@Component({
    selector: 'app-contacts',
    standalone: true,
    imports: [CommonModule, FormsModule, TranslateModule, IconComponent, ContactFormModalComponent],
    templateUrl: './contacts.component.html',
    styleUrls: ['./contacts.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class ContactsComponent implements OnInit {
    contacts$ = this.contactService.contacts$;

    isModalOpen = false;
    contactToEdit: Contact | null = null;

    constructor(
        private contactService: ContactService,
        private toastService: ToastService,
        private confirmModalService: ConfirmModalService
    ) { }

    ngOnInit(): void {
    }

    openAddModal(): void {
        this.contactToEdit = null;
        this.isModalOpen = true;
    }

    openEditModal(contact: Contact): void {
        this.contactToEdit = contact;
        this.isModalOpen = true;
    }

    closeModal(): void {
        this.isModalOpen = false;
        this.contactToEdit = null;
    }

    saveContact(data: { address: string; label: string }): void {
        if (this.contactToEdit) {
            this.contactService.updateContact(data.address, data.label);
        } else {
            this.contactService.addContact({
                address: data.address,
                label: data.label
            });
        }
        this.toastService.success(this.contactToEdit ? 'CONTACTS.UPDATED_SUCCESS' : 'CONTACTS.ADDED_SUCCESS');
        this.closeModal();
    }

    async deleteContact(address: string): Promise<void> {
        const confirmed = await this.confirmModalService.confirm('Are you sure you want to delete this contact?');
        if (confirmed) {
            this.contactService.removeContact(address);
            this.toastService.success('CONTACTS.DELETED_SUCCESS');
        }
    }

    async copyAddress(address: string): Promise<void> {
        try {
            await navigator.clipboard.writeText(address);
            this.toastService.success('CONTACTS.COPIED_SUCCESS');
        } catch (e) {
            this.toastService.error('Failed to copy address');
        }
    }
}
